// Eingabe kürzen und ein Kostenlimit pro Tag und pro Sitzung erzwingen (Zähler in Static Data, nur Produktiv-Läufe).
const MAX_PER_DAY = 10;
const MAX_PER_SESSION = 10;
const body = $input.first().json.body || {};
const sd = $getWorkflowStaticData('global');
const day = new Date().toISOString().slice(0, 10);
if (sd.limitDay !== day) { sd.limitDay = day; sd.limitTotal = 0; sd.limitSessions = {}; }
const sid = String(body.sessionId || 'anon').slice(0, 64);
const used = sd.limitSessions[sid] || 0;
let allowed = true, reason = '';
if (sd.limitTotal >= MAX_PER_DAY) { allowed = false; reason = 'total'; }
else if (used >= MAX_PER_SESSION) { allowed = false; reason = 'session'; }
if (allowed) { sd.limitTotal += 1; sd.limitSessions[sid] = used + 1; }
const chatInput = String(body.chatInput || '').slice(0, 600).trim();
let context = body.context && typeof body.context === 'object' ? body.context : {};
const contextJson = JSON.stringify(context).slice(0, 1500);
return [{ json: { chatInput: chatInput || 'Hallo', sessionId: sid, contextJson, allowed, reason, remainingToday: Math.max(0, MAX_PER_DAY - sd.limitTotal) } }];

// Modellausgabe in {reply, actions} umwandeln: Codeblöcke entfernen, JSON suchen, nur bekannte Aktionen durchlassen.
const ALLOWED = ['flyTo','showPlace','setRoute','play','pause','setMode','setTime','showMountain','openWeather','compareModes'];
const raw = String($input.first().json.output ?? '');
let txt = raw.replace(/```(?:json)?/gi, '').trim();
let data = null;
try { data = JSON.parse(txt); } catch (e) {
  const a = txt.indexOf('{'), b = txt.lastIndexOf('}');
  if (a >= 0 && b > a) { try { data = JSON.parse(txt.slice(a, b + 1)); } catch (e2) { data = null; } }
}
if (!data || typeof data !== 'object') data = { reply: txt || 'Entschuldige, das habe ich nicht verstanden.', actions: [] };
const actions = Array.isArray(data.actions) ? data.actions.filter(x => x && ALLOWED.includes(x.type)).slice(0, 4) : [];
const reply = String(data.reply || '').slice(0, 1200) || 'Erledigt.';
return [{ json: { reply, actions } }];

const r = $input.first().json.reason;
const reply = r === 'session'
  ? 'Für dieses Gespräch ist das Kontingent aufgebraucht. Einfache Befehle wie „Zürich nach Luzern“ oder „Spiel ab“ funktionieren trotzdem.'
  : 'Der KI-Assistent hat sein Tageskontingent von 10 Nachrichten erreicht, morgen geht es weiter. Einfache Befehle wie „Zürich nach Luzern“ oder „Spiel ab“ funktionieren weiterhin.';
return [{ json: { reply, actions: [] } }];
